import { button, badge, emptyState, escapeHtml as e } from "./ui.js";
import { icon } from "./icons.js";
import { subjects } from "./network-analytics.js";
import { demoDate } from "./chairman-data.js";
import { panel, metric, table, select, sparkline } from "./chairman.js";
import { coursesPage } from "./learning.js";
import { sectionCourseProgress } from "./section-data.js";
import { sectionReportPreview } from "./section-head.js";
import { gradeViews, gradeReportTypes, gradeScope, gradeAcademic, gradeAttendance, gradeCourses, gradeTeachers, gradeFollowups, gradeClassUpdates, gradeClassStatuses, gradeTaskStatuses, gradeOverview, visibleGradeReports } from "./grade-data.js";
import { subjectRequestInbox } from "./subject-support.js";
import { classRequestInbox } from "./class-support.js";
import { gradeSupportList } from "./grade-support.js";

const pct = (value) => Number(value).toFixed(1) + "%";
const mark = (row) => row.count ? pct(row.mean) : "—";
const statusLabels = { present: "Present", absent: "Absent", late: "Late", leave: "On leave" };
const heading = (title, text, actions = "") => `<header class="chairman-page-heading"><div><h1>${title}</h1><p>${text}</p></div><div class="chairman-heading-actions">${badge("Sample data", "amber")}${actions}</div></header>`;
const link = (view, text) => `<a href="#coordinator/overview/${view}" class="button secondary compact">${text}</a>`;
const choices = (values, current) => values.map(([id, name]) => `<option value="${e(id)}" ${String(id) === String(current) ? "selected" : ""}>${e(name)}</option>`).join("");

function identity(options, scope) {
  const entries = options.state.accounts.flatMap((person) => person.grants.map((grant, index) => ({ person, grant, index }))).filter(({ grant }) => grant.role === "coordinator");
  const selected = options.context.account.id + "|" + options.context.account.grants.indexOf(options.context.grant);
  return `<header class="section-identity"><div><span class="chairman-eyebrow">GRADE COORDINATOR WORKSPACE</span><h1>${scope.grade === 0 ? "Preschool" : "Grade " + scope.grade}</h1><p>${e(scope.branch.school)} · ${e(scope.section.name)}</p></div><label class="principal-demo-account"><span>Demo Grade Coordinator</span><span class="select-wrap"><select aria-label="Preview Grade Coordinator" data-change="account">${choices(entries.map(({ person, grant, index }) => [person.id + "|" + index, person.name + " · " + options.state.branches.find((branch) => branch.id === grant.branch)?.name + " · Grade " + grant.grade]), selected)}</select>${icon("chevronDown", 14)}</span></label></header>`;
}

function filters(options, scope, kind) {
  const f = options.gradeCoordinator;
  return `<div class="chairman-filters grade-filters"><div class="grade-fixed-scope">${icon("school", 18)}<div><small>Assigned grade</small><strong>${scope.grade === 0 ? "Preschool" : "Grade " + scope.grade}</strong></div></div>${scope.grade > 0 ? select("Class", "grade-class", [["all", "All grade classes"], ...["A", "B"].map((letter) => [scope.grade + letter, "Class " + scope.grade + letter])], f.className) : ""}${["academic", "reports"].includes(kind) ? select("Assessment subject", "grade-subject", subjects.map((subject) => [subject.id, subject.name]), f.subject) + select("Assessment term", "grade-term", [1, 2, 3].map((term) => [term, "Term " + term]), f.term) : ""}${["attendance", "coordination", "reports"].includes(kind) ? `<label class="chairman-filter"><span>Reporting date</span><input type="date" aria-label="Reporting date" data-change="grade-date" min="2026-10-12" max="${demoDate}" value="${f.date}"></label>` : ""}${["attendance", "reports"].includes(kind) ? select("Attendance period", "grade-period", [["day", "One school day"], ["week", "Last 5 school days"], ["month", "Last 20 school days"]], f.period) : ""}</div>`;
}

function followupPanel(options) {
  const items = gradeFollowups(options.state, options.context), people = [{ id: options.context.account.id, name: options.context.account.name }, ...gradeTeachers(options.state, options.context)];
  const rows = items.map((item) => `<tr><td><strong>${e(item.name)}</strong><small>Class ${e(item.className)} · ${e(item.admission)}</small></td><td>${e(people.find((person) => person.id === item.owner)?.name || "Grade office")}</td><td>${e(item.due)}</td><td>${badge(gradeTaskStatuses[item.status], item.status === "resolved" ? "green" : "amber")}</td><td>${button("Update follow-up", "grade-followup-edit", { value: item.id, variant: "secondary compact" })}</td></tr>`).join("");
  return panel("Grade attendance follow-ups", "Owned tasks and note history within your assigned grade", items.length ? table(["Student", "Owner", "Due", "Status", "Action"], rows, "Grade follow-ups") : emptyState("checkCircle", "No grade follow-ups recorded", "Open a student’s attendance calendar to record a follow-up."));
}

function classRows(options, scope) {
  const f = options.gradeCoordinator, academic = gradeAcademic(options.state, options.context, { ...f, className: "all" }), attendance = gradeAttendance(options.state, options.context, { ...f, className: "all" }), updates = gradeClassUpdates(options.state, options.context);
  const courses = gradeCourses(options.state, options.context);
  return attendance.classes.filter((row) => f.className === "all" || row.className === f.className).map((row) => {
    const score = academic.classes.find((item) => item.className === row.className), update = updates.find((item) => item.className === row.className);
    const mentor = options.state.accounts.find((person) => person.grants.some((grant) => grant.role === "class_teacher" && grant.branch === scope.branch.id && Number(grant.grade) === scope.grade && grant.className === row.className));
    return `<tr><td><button type="button" class="chairman-person-link" data-action="grade-open-class" data-value="${row.className}">Class ${row.className}</button><small>${e(mentor?.name || "Class teacher not appointed")}</small></td><td>${score ? mark(score) : "—"}</td><td>${pct(row.rate)}</td><td>${courses.filter((course) => course.className === row.className).length}</td><td>${badge(gradeClassStatuses[update?.status] || "Not reviewed", update?.status === "needs_support" ? "amber" : "neutral")}${update?.notes[0] ? `<small>${e(update.notes[0].text)}</small>` : ""}</td><td>${button("Record class review", "grade-class-review", { value: row.className, variant: "secondary compact" })}</td></tr>`;
  }).join("");
}

function overview(options, scope) {
  const data = gradeOverview(options.state, options.context);
  return heading("Grade Overview", "Learning, class attendance and daily coordination within your appointed grade.", link("academic", "Review learning")) + `<div class="chairman-metrics">${metric("Sample student attendance", data.attendance.summary.expected ? pct(data.attendance.summary.rate) : "—", "20 Nov · Illustrative grade register", "checkCircle")}${metric("Registered students", data.registered, "Actual prototype admission records", "users", "blue")}${metric("Prototype subjects", data.courses.length, "Assigned grade only", "book")}${metric("Pending follow-ups", data.followups.filter((item) => item.status !== "resolved").length, "Recorded grade attendance tasks", "clock", "amber")}</div>` +
    `<div class="section-summary-strip"><div><span>Published materials</span><strong>${data.materials}</strong></div><div><span>Materials marked done</span><strong>${data.completed} / ${data.expected}</strong></div><div><span>Support requests open</span><strong>${data.requests.filter((item) => item.status !== "resolved").length}</strong></div><div><span>Classes needing support</span><strong>${data.updates.filter((item) => item.status === "needs_support").length}</strong></div></div>` +
    `<div class="section-attention"><div><h2>Grade priorities</h2><p>${data.missing} subjects without lecture materials · ${data.teachers.filter((person) => person.status !== "present").length} staff serving this grade unavailable on the sample day.</p></div>${link("coordination", "Review classes")}</div>` +
    panel("Classes in your grade", "Term 3 Mathematics samples and daily attendance · Class reviews are recorded separately", table(["Class / mentor", "Average", "Attendance", "Subjects", "Coordination", "Action"], classRows({ ...options, gradeCoordinator: { ...options.gradeCoordinator, className: "all", subject: "mathematics", term: 3, date: demoDate, period: "day" } }, scope), "Grade class overview")) +
    panel("Five-day attendance trend", "Illustrative grade students · Late arrivals count as present", sparkline(gradeAttendance(options.state, options.context, { period: "week" }).trend, "Grade attendance trend")) + followupPanel(options);
}

function courseTable(options) {
  const courses = gradeCourses(options.state, options.context, options.gradeCoordinator);
  const rows = courses.map((course) => { const progress = sectionCourseProgress(options.state, course); return `<tr><td><strong>${e(course.title)}</strong><small>Class ${e(course.className)}</small></td><td>${e(progress.teacher)}</td><td>${progress.enrolled}</td><td>${progress.materials}</td><td>${progress.completed} / ${progress.expected}</td><td><div class="section-row-actions">${button("Materials & progress", "open-course", { value: course.id, variant: "secondary compact" })}${button("Edit enrolment", "assign", { value: course.id, variant: "secondary compact" })}</div></td></tr>`; }).join("");
  return panel("Subjects and student enrolment", "Matching-class students only · The assigned teacher is retained · Subject list is independent of assessment subject", courses.length ? table(["Subject", "Assigned teacher", "Enrolled", "Materials", "Done / assigned", "Actions"], rows, "Grade subjects") : emptyState("book", "No prototype subjects in this class", "Choose another class in your grade. Sample comparisons do not create subject records."));
}

function academic(options, scope) {
  if (gradeCourses(options.state, options.context).some((course) => course.id === options.courseId)) return coursesPage(options);
  const result = gradeAcademic(options.state, options.context, options.gradeCoordinator), f = options.gradeCoordinator, details = f.compare !== "subjects";
  return heading("Academic & Subjects", "Compare classes and subjects, review materials and coordinate student enrolment.") + filters(options, scope, "academic") + `<div class="chairman-metrics">${metric("Subject average", mark(result.summary), result.subjectName + " · Grade " + scope.grade, "book")}${metric("Pass rate", result.summary.count ? pct(result.summary.passRate) : "—", result.summary.count + " sample students assessed", "checkCircle", "blue")}${metric("Classes assessed", result.classes.length, "Selected grade/class sample", "users")}${metric("Prototype subjects", gradeCourses(options.state, options.context, f).length, "Subject enrolment stays in your grade", "file", "amber")}</div>` +
    panel("Grade academic comparison", "Sample assessment cohorts are separate from subject enrolments", `<div class="chairman-panel-filter">${select("Compare by", "grade-compare", [["classes", "Classes"], ["subjects", "Subjects"], ["teachers", "Assigned teachers"]], f.compare)}</div>` + table([f.compare === "subjects" ? "Subject" : f.compare === "teachers" ? "Teacher" : "Class", ...(details ? [f.compare === "teachers" ? "Classes" : "Assigned teacher"] : []), "Average", "Pass rate", "Sample assessed"], result.rows.map((row) => `<tr><td>${e(row.name)}</td>${details ? `<td>${e(row.detail || "")}</td>` : ""}<td>${mark(row)}</td><td>${row.count ? pct(row.passRate) : "—"}</td><td>${row.count}</td></tr>`).join(""), "Grade academic comparison"), button("Comparison CSV", "grade-export", { value: "academic", variant: "secondary compact", iconName: "download" })) + courseTable(options);
}

function attendance(options, scope) {
  const f = options.gradeCoordinator, result = gradeAttendance(options.state, options.context, f), page = Math.min(f.page, Math.max(1, Math.ceil(result.rows.length / 12))), start = (page - 1) * 12;
  return heading("Attendance", "Read class registers and coordinate follow-ups for students in your grade.", button("Attendance CSV", "grade-export", { value: "attendance", variant: "secondary", iconName: "download" })) + filters(options, scope, "attendance") +
    `<p class="chairman-filter-note">${result.dates[0]} – ${result.dates.at(-1)} · ${result.dates.length} school day(s) · Illustrative register. Period totals count attendance-days; late arrivals are included in present totals.</p><div class="chairman-metrics">${metric("Attendance rate", result.summary.expected ? pct(result.summary.rate) : "—", "Assigned grade and selected class", "checkCircle")}${metric("Present", result.summary.present, "Out of " + result.summary.expected + " expected attendance-days", "users", "blue")}${metric("Absent", result.summary.absent, "Selected reporting period", "alert", "amber")}${metric("Late arrivals", result.summary.late, "Included in present totals", "clock")}</div>` +
    `<div class="chairman-two-columns">${panel("Class attendance", "Select a class to open its register", table(["Class", "Rate", "Present", "Absent", "Late"], result.classes.map((row) => `<tr><td><button class="chairman-person-link" type="button" data-action="grade-open-class" data-value="${row.className}">Class ${row.className}</button></td><td>${pct(row.rate)}</td><td>${row.present}</td><td>${row.absent}</td><td>${row.late}</td></tr>`).join(""), "Grade class attendance"))}${panel("Attendance trend", "Selected reporting period · Assigned grade only", sparkline(result.trend, "Grade register trend"))}</div>` +
    panel("Student attendance register", "Select a student for 20 school days and a follow-up note", `<div class="chairman-list-tools">${select("Attendance watchlist", "grade-flag", [["all", "All grade students"], ["repeated", "3+ absences in 20 days"], ["absent", "Absent on latest day"], ["late", "Late on latest day"]], f.flag)}<label class="chairman-search">${icon("search", 16)}<input type="search" aria-label="Search grade student" data-change="grade-query" data-focus="grade-search" placeholder="Search student or admission" value="${e(f.query)}"></label></div>` + table(["Student", "Class", "Absences in 20 days", "Latest status"], result.rows.slice(start, start + 12).map((student) => `<tr><td><button type="button" class="chairman-person-link" data-action="grade-student" data-value="${student.id}">${e(student.name)}</button><small>${e(student.admission)}</small></td><td>Class ${student.className}</td><td>${student.missed}</td><td>${badge(statusLabels[student.status], student.status === "present" ? "green" : "amber")}</td></tr>`).join(""), "Grade student register") + `<div class="chairman-pager"><span>${result.rows.length ? start + 1 : 0}–${Math.min(start + 12, result.rows.length)} of ${result.rows.length}</span><div>${button("Previous", "grade-page", { value: page - 1, variant: "secondary compact", extra: page <= 1 ? "disabled" : "" })}<span>Page ${page}</span>${button("Next", "grade-page", { value: page + 1, variant: "secondary compact", extra: start + 12 >= result.rows.length ? "disabled" : "" })}</div></div>`) + followupPanel(options);
}

function coordination(options, scope) {
  const teachers = gradeTeachers(options.state, options.context, options.gradeCoordinator), courses = gradeCourses(options.state, options.context, options.gradeCoordinator);
  return heading("Class Coordination", "Record class reviews, check learning readiness and request Section Head support.") + filters(options, scope, "coordination") +
    classRequestInbox(options) + subjectRequestInbox(options) + panel("Class coordination reviews", (subjects.find((subject) => subject.id === options.gradeCoordinator.subject)?.name || "Subject") + " · Term " + options.gradeCoordinator.term + " sample averages · Attendance uses " + ({ day: 1, week: 5, month: 20 }[options.gradeCoordinator.period]) + " school day(s). Review notes do not change marks or registers.", table(["Class / mentor", "Sample average", "Attendance", "Subjects", "Latest review", "Action"], classRows(options, scope), "Grade class coordination")) +
    panel("Teachers serving this grade", "Only grade subjects and relevant class/grade appointments are included", table(["Staff member", "Grade classes", "Grade subjects", "Availability"], teachers.map((person) => `<tr><td><button class="chairman-person-link" type="button" data-action="grade-teacher" data-value="${person.id}">${e(person.name)}</button><small>${e(person.role)}</small></td><td>${e(person.classes.join(", "))}</td><td>${person.courses.length}</td><td>${badge(statusLabels[person.status], person.status === "present" ? "green" : "amber")}</td></tr>`).join(""), "Grade teaching staff")) +
    panel("Subject readiness and support", "Material reviews belong to the Section Head; cover allocation belongs to the Vice Principal", table(["Subject", "Assigned teacher", "Materials", "Section review", "Action"], courses.map((course) => { const p = sectionCourseProgress(options.state, course); return `<tr><td><strong>${e(course.title)}</strong><small>Class ${e(course.className)}</small></td><td>${e(p.teacher)}</td><td>${p.materials || badge("Materials missing", "amber")}</td><td>${p.review ? p.review.status === "ready" ? "Ready for learning" : "Updates requested" : "Not reviewed"}</td><td>${button("Request Section Head support", "grade-support", { value: course.id, variant: "secondary compact" })}</td></tr>`; }).join(""), "Grade subject coordination")) +
    panel("Support requests and responses", "Requests go into the same school and section’s demo queue; responses are recorded in this browser", gradeSupportList(options));
}

function reports(options, scope) {
  const f = options.gradeCoordinator, history = visibleGradeReports(options.state, options.context), current = history.find((report) => report.id === f.reportId);
  return heading("Grade Reports", "Capture grade learning, attendance and class coordination for the Section Head.") + `<div class="section-report-builder surface"><div>${select("Report type", "grade-report-type", Object.entries(gradeReportTypes), f.reportType)}${f.reportType === "academic" ? select("Comparison", "grade-compare", [["classes", "Classes"], ["subjects", "Subjects"], ["teachers", "Assigned teachers"]], f.compare) : ""}</div>${filters(options, scope, "reports")}<div class="section-report-generate"><p>${icon("school", 17)}${e(scope.branch.name)} · Grade ${scope.grade} only</p>${button("Generate grade report", "grade-generate-report", { iconName: "file" })}</div></div><section class="surface chairman-report-result"><div class="chairman-report-actions">${current ? select("Download format", "grade-report-format", [["csv", "CSV spreadsheet"], ["html", "Standalone HTML"]], f.reportFormat) + button("Download report", "grade-download-report", { value: current.id, variant: "secondary", iconName: "download" }) + button("Print / Save PDF", "grade-print-report", { value: current.id, variant: "secondary", iconName: "file" }) : "Report preview"}</div>${current ? sectionReportPreview(current) : emptyState("file", "Your grade report starts here", "Choose a report and filters, then generate a snapshot to preview, download or print.")}</section>` +
    panel("Saved grade snapshots", "Latest eight snapshots per school/grade, separate from Section Head and senior leadership reports", `<div class="chairman-report-history">${history.map((item) => `<button class="chairman-history-card ${item.id === current?.id ? "is-selected" : ""}" type="button" data-action="grade-open-report" data-value="${item.id}">${icon("file", 20)}<span><strong>${e(item.title)}</strong><small>Grade ${scope.grade} · ${e(item.criteria.to)} · ${item.customRows.length} rows</small></span>${badge("Sample", "neutral")}</button>`).join("") || '<p class="chairman-no-history">Generated grade reports will appear here.</p>'}</div>`);
}

export function gradeCoordinatorPage(options) {
  const scope = gradeScope(options.state, options.context);
  if (!scope) return emptyState("school", "No grade assigned", "A Grade Coordinator appointment with a school and grade is required.");
  const view = options.gradeCoordinator.view;
  return `<section class="chairman-portal section-portal grade-portal">${identity(options, scope)}<nav class="chairman-view-bar section-view-bar" aria-label="Grade Coordinator views">${gradeViews.map((item) => `<a href="#coordinator/overview/${item.id}" aria-label="${item.name}" ${item.id === view ? 'aria-current="page" class="is-active"' : ""}>${icon(item.icon, 18)}<span class="chairman-view-full">${item.name}</span><span class="chairman-view-short">${item.short}</span></a>`).join("")}</nav><div class="chairman-analytics section-analytics">${({ summary: overview, academic, attendance, coordination, reports })[view](options, scope)}</div></section>`;
}

export function gradeClassReviewForm(options, className) {
  const previous = gradeClassUpdates(options.state, options.context).find((item) => item.className === className);
  return `<form data-form="grade-class-review"><div class="form-body"><input type="hidden" name="className" value="${e(className)}"><h3>Class ${e(className)}</h3><label class="field">Class review status<select name="status">${choices(Object.entries(gradeClassStatuses), previous?.status || "on_track")}</select></label><label class="field">Class coordination note<textarea name="note" maxlength="1000" rows="4" required placeholder="Record teaching progress or support needed"></textarea></label>${previous ? '<div class="vice-note-history"><h3>Previous class reviews</h3>' + previous.notes.map((note) => `<article><p>${e(note.text)}</p><small>${e(note.by)} · ${e(note.at.slice(0, 10))}</small></article>`).join("") + '</div>' : ""}<p class="chairman-filter-note">This records coordination progress; sample attendance and assessment marks stay unchanged.</p></div><p class="form-error" role="alert" hidden></p><footer class="dialog-actions">${button("Cancel", "close-dialog", { variant: "secondary" })}<button class="button primary" type="submit">Save class review</button></footer></form>`;
}
